import os, json, csv, re, sys
import numpy as np

N = 26
P_PROM_BOUND = 'storage/prometheus/nmap/n26/active_boundary_tol1e08.csv'
P_PROM_KKT_JSON = 'storage/prometheus/SOTA_550_kkt_pairs.json'
P_PROM_KKT_CSV  = 'storage/prometheus/nmap/n26/kkt_multipliers_pairs.csv'
P_NOE_KKT = 'storage/noesis/exports/shadow_prices_tol1e8.csv'
P_NOE_C = 'storage/noesis/latest_centers.txt'
P_NOE_R = 'storage/noesis/latest_radii.txt'
OUT_SUM = 'storage/noesis/exports/appendix_prometheus_kkt_compare_v3.json'

def load_noesis_snapshot():
    if os.path.exists(P_NOE_C) and os.path.exists(P_NOE_R):
        c = np.loadtxt(P_NOE_C, dtype=float).reshape(N,2)
        r = np.loadtxt(P_NOE_R, dtype=float).reshape(N,)
    else:
        centers = []
        radius = 0.08
        for i in range(5):
            for j in range(6):
                if len(centers) < N:
                    centers.append([0.1 + 0.2*i, 0.1 + 0.15*j])
        c = np.array(centers, float); r = np.full(N, radius, float)
    return c, r

def load_boundary_discs_csv(path):
    discs = set()
    if not os.path.exists(path): return discs
    with open(path, 'r', newline='') as f:
        rdr = csv.reader(f)
        header = next(rdr, None)
        idx_disc = None
        if header:
            for k, name in enumerate(header):
                nm = str(name).strip().lower()
                if nm in ('disc','i','index','id','node','circle'):
                    idx_disc = k; break
        else:
            f.seek(0); rdr = csv.reader(f)
        for row in rdr:
            if not row: continue
            if idx_disc is not None:
                try:
                    d = int(row[idx_disc])
                    if 0 <= d < N: discs.add(d)
                    continue
                except Exception:
                    pass
            m = re.search(r'-?\d+', ' '.join(row))
            if m:
                d = int(m.group(0))
                if 0 <= d < N: discs.add(d)
    return discs

def load_noesis_kkt_csv(path, interior_exclude):
    pairs = []
    if not os.path.exists(path): return pairs
    with open(path, 'r', newline='') as f:
        try:
            rdr = csv.DictReader(f)
            key_i = next((k for k in rdr.fieldnames if k and k.lower() in ('i','disc_i','a','idx_i','u')), None)
            key_j = next((k for k in rdr.fieldnames if k and k.lower() in ('j','disc_j','b','idx_j','v')), None)
            key_v = next((k for k in rdr.fieldnames if k and k.lower() in ('lambda','multiplier','value','shadow_price','w')), None)
            if key_i and key_j and key_v:
                for row in rdr:
                    try:
                        i = int(row[key_i]); j = int(row[key_j]); val = float(row[key_v])
                    except Exception:
                        continue
                    if 0 <= i < N and 0 <= j < N and i != j:
                        a,b = (i,j) if i<j else (j,i)
                        if a in interior_exclude or b in interior_exclude: continue
                        pairs.append((a,b,val))
            else:
                f.seek(0); rdr2 = csv.reader(f)
                for row in rdr2:
                    if len(row) < 3: continue
                    try:
                        i, j = int(row[0]), int(row[1]); val = float(row[2])
                    except Exception:
                        continue
                    if 0 <= i < N and 0 <= j < N and i != j:
                        a,b = (i,j) if i<j else (j,i)
                        if a in interior_exclude or b in interior_exclude: continue
                        pairs.append((a,b,val))
        except Exception:
            pass
    best = {}
    for a,b,v in pairs:
        best[(a,b)] = max(v, best.get((a,b), -np.inf))
    out = [(a,b,v) for (a,b),v in best.items()]
    out.sort(key=lambda t: t[2], reverse=True)
    return out

def _append_pair(pairs, i, j, val, interior_exclude):
    if not (0 <= i < N and 0 <= j < N and i != j): return
    a,b = (i,j) if i<j else (j,i)
    if a in interior_exclude or b in interior_exclude: return
    if not np.isfinite(val): return
    pairs.append((a,b,float(val)))

def load_prom_kkt_json(path, interior_exclude):
    pairs = []
    if not os.path.exists(path): return pairs
    try:
        data = json.load(open(path, 'r'))
    except Exception:
        return pairs
    def parse_any(obj):
        if isinstance(obj, dict):
            # common container keys
            for key in ('kkt_ranked_pairs','pairs','ranked','data','items'):
                if key in obj:
                    parse_any(obj[key])
            # dict mapping
            for k,v in obj.items():
                if isinstance(v, (list,dict)): continue
            # dict entries with i,j and lambda
            if 'i' in obj and 'j' in obj and ('lambda' in obj or 'multiplier' in obj or 'value' in obj or 'w' in obj):
                try:
                    i = int(obj.get('i')); j = int(obj.get('j'))
                    val = float(obj.get('lambda', obj.get('multiplier', obj.get('value', obj.get('w')))))
                    _append_pair(pairs, i, j, val, interior_exclude)
                except Exception:
                    pass
        elif isinstance(obj, list):
            for e in obj:
                parse_any(e)
    parse_any(data)
    # dedup max
    best = {}
    for a,b,v in pairs:
        best[(a,b)] = max(v, best.get((a,b), -np.inf))
    out = [(a,b,v) for (a,b),v in best.items()]
    out.sort(key=lambda t: t[2], reverse=True)
    return out

def load_prom_kkt_csv(path, interior_exclude):
    pairs = []
    if not os.path.exists(path): return pairs
    with open(path, 'r', newline='') as f:
        try:
            rdr = csv.DictReader(f)
            key_i = next((k for k in rdr.fieldnames if k and k.lower() in ('i','disc_i','a','idx_i','u')), None)
            key_j = next((k for k in rdr.fieldnames if k and k.lower() in ('j','disc_j','b','idx_j','v')), None)
            key_v = next((k for k in rdr.fieldnames if k and k.lower() in ('lambda','multiplier','value','shadow_price','w')), None)
            if not (key_i and key_j and key_v):
                f.seek(0); rdr2 = csv.reader(f)
                for row in rdr2:
                    if len(row) < 3: continue
                    try:
                        i, j, val = int(row[0]), int(row[1]), float(row[2])
                    except Exception:
                        continue
                    _append_pair(pairs, i, j, val, interior_exclude)
            else:
                for row in rdr:
                    try:
                        i, j, val = int(row[key_i]), int(row[key_j]), float(row[key_v])
                    except Exception:
                        continue
                    _append_pair(pairs, i, j, val, interior_exclude)
        except Exception:
            pass
    best = {}
    for a,b,v in pairs:
        best[(a,b)] = max(v, best.get((a,b), -np.inf))
    out = [(a,b,v) for (a,b),v in best.items()]
    out.sort(key=lambda t: t[2], reverse=True)
    return out

def topk_pairs(sorted_pairs, K): return [(a,b) for (a,b,_) in sorted_pairs[:K]]
def jaccard(A,B):
    A,B = set(A), set(B)
    if not A and not B: return 1.0
    return len(A & B)/len(A | B) if (A or B) else 1.0

def main():
    prom_boundary = load_boundary_discs_csv(P_PROM_BOUND)
    # Interior filter = exclude boundary discs from each ranking
    noe_kkt = load_noesis_kkt_csv(P_NOE_KKT, prom_boundary)
    prom_kkt_json = load_prom_kkt_json(P_PROM_KKT_JSON, prom_boundary)
    prom_kkt_csv  = load_prom_kkt_csv(P_PROM_KKT_CSV,  prom_boundary)
    # Prefer the richer of JSON/CSV
    prom_kkt = prom_kkt_csv if len(prom_kkt_csv) >= len(prom_kkt_json) else prom_kkt_json

    K9, K8 = 25, 15
    noe_top9, noe_top8 = topk_pairs(noe_kkt, K9), topk_pairs(noe_kkt, K8)
    prom_top9, prom_top8 = topk_pairs(prom_kkt, K9), topk_pairs(prom_kkt, K8)

    j_top9 = jaccard(noe_top9, prom_top9)
    j_top8 = jaccard(noe_top8, prom_top8)

    summary = {
        "assumptions": {
            "interior_filter_source": "prometheus active_boundary_tol1e08.csv",
            "policy": "sets-only ingestion; no peer coordinates or code used"
        },
        "sources": {
            "prometheus_kkt_json": P_PROM_KKT_JSON,
            "prometheus_kkt_csv": P_PROM_KKT_CSV,
            "prometheus_boundary_csv": P_PROM_BOUND,
            "noesis_kkt_csv": P_NOE_KKT
        },
        "counts": {
            "noesis_kkt_pairs": len(noe_kkt),
            "prometheus_kkt_pairs": len(prom_kkt),
            "noesis_top9": len(noe_top9),
            "noesis_top8": len(noe_top8),
            "prometheus_top9": len(prom_top9),
            "prometheus_top8": len(prom_top8)
        },
        "topK": {
            "noesis_top9": noe_top9,
            "noesis_top8": noe_top8,
            "prometheus_top9": prom_top9,
            "prometheus_top8": prom_top8
        },
        "overlaps": {
            "jaccard_top9_kkt": j_top9,
            "jaccard_top8_kkt": j_top8
        }
    }

    os.makedirs(os.path.dirname(OUT_SUM), exist_ok=True)
    with open(OUT_SUM, 'w') as f:
        json.dump(summary, f, indent=2)

    print("[APPENDIX-KKT v3] counts:", summary["counts"])
    print("[APPENDIX-KKT v3] J_top9=", j_top9, "J_top8=", j_top8)
    print("[APPENDIX-KKT v3] out:", OUT_SUM)

    centers, radii = load_noesis_snapshot()
    radii = np.maximum(radii - 1e-9, 1e-12)
    return centers.astype(float), radii.astype(float)

def construct_packing():
    return main()
